BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog;
WITH targets AS (SELECT unnest(ARRAY['public.fn_agenda_excepciones_sucursal_bloques_validar_modo()','public.fn_agenda_excepciones_sucursal_validar_compatibilidad()','public.fn_bloquear_delete_fisico()','public.fn_bloquear_persona_cliente_empleado()','public.fn_citas_grupos_set_defaults()','public.fn_citas_integrantes_set_updated_at()','public.fn_citas_integrantes_validate_limits()','public.fn_citas_set_integrante_from_legacy()','public.fn_comprobantes_agendamiento_set_defaults()','public.fn_comprobantes_destinatarios_set_updated_at()','public.fn_desactivar_tarifas_base_de_servicio()','public.fn_facturas_set_updated_at()','public.fn_guardar_desactivacion_servicio()','public.fn_marcar_no_show(integer, integer)','public.fn_points_estado_final_cita()','public.fn_points_get_effective_rule(uuid)','public.fn_points_get_or_create_active_cycle(uuid, integer, timestamp with time zone)','public.fn_points_get_or_create_active_cycle(uuid, timestamp with time zone)','public.fn_points_materialize_expired_cycles(uuid)','public.fn_points_tx_apply_tipo_sign()','public.fn_points_tx_guard_acumular_final()','public.fn_prevent_block_protected_correo()','public.fn_prevent_block_protected_persona()','public.fn_prevent_block_protected_role()','public.fn_prevent_block_protected_usuario()','public.fn_set_updated_at()','public.fn_trg_otorgar_puntos_plan_confirmada()','public.fn_trg_otorgar_puntos_por_cita()','public.fn_trg_roles_usuarios_unicidad_scope()','public.fn_trg_validar_cliente_persona_en_cita()','public.fn_validar_paquete_activo_minimo_servicios()','public.fn_validar_paquete_activo_sin_servicios_inactivos()','public.fn_validar_persona_empleado_campos_obligatorios()','public.fn_validar_servicio_activo_con_tarifa_base()','public.set_current_timestamp_updated_at()','public.validate_membership_plan_beneficios()','public.fn_citas_detalles_line_identity_v2()','public.fn_hold_defaults_y_unico()','public.fn_es_admin_de_sucursal(uuid, uuid)','public.fn_is_super_admin(uuid)','public.fn_has_role(uuid, text)']::text[]) signature),
routines AS (SELECT s.signature,p.*,n.nspname,l.lanname FROM targets s LEFT JOIN pg_proc p ON p.oid=to_regprocedure(s.signature) LEFT JOIN pg_namespace n ON n.oid=p.pronamespace LEFT JOIN pg_language l ON l.oid=p.prolang)
SELECT jsonb_build_object('captured_at',clock_timestamp(),'server_version',version(),'user',current_user,
'routines',(SELECT jsonb_agg(jsonb_build_object(
'signature',signature,'oid',oid,'definition',pg_get_functiondef(oid),'prosrc',prosrc,
'body_md5',md5(replace(prosrc,chr(13)||chr(10),chr(10))),'definition_md5',md5(pg_get_functiondef(oid)),
'owner',pg_get_userbyid(proowner),'kind',prokind,'return_type',format_type(prorettype,null),
'security_definer',prosecdef,'config',proconfig,'acl',proacl::text,'language',lanname,
'identity_args',pg_get_function_identity_arguments(oid),
'execute_acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END) FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a),
'references',(SELECT coalesce(jsonb_agg(jsonb_build_object('object',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid),'type',d.deptype) ORDER BY pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid)),'[]') FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=r.oid),
'dependents',(SELECT coalesce(jsonb_agg(jsonb_build_object('object',pg_describe_object(d.classid,d.objid,d.objsubid),'type',d.deptype) ORDER BY pg_describe_object(d.classid,d.objid,d.objsubid)),'[]') FROM pg_depend d WHERE d.refclassid='pg_proc'::regclass AND d.refobjid=r.oid),
'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'internal',t.tgisinternal) ORDER BY pg_get_triggerdef(t.oid)),'[]') FROM pg_trigger t WHERE t.tgfoid=r.oid)
) ORDER BY signature) FROM routines r),
'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'super',rolsuper,'bypassrls',rolbypassrls,'createrole',rolcreaterole,'createdb',rolcreatedb) ORDER BY rolname) FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role','authenticator','postgres') OR rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb),
'schemas',(SELECT jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text,'anon_create',has_schema_privilege('anon',oid,'CREATE'),'authenticated_create',has_schema_privilege('authenticated',oid,'CREATE')) ORDER BY nspname) FROM pg_namespace WHERE nspname IN ('public','auth','app_private')),
'backup_exists',to_regclass('app_private.security02_routine_backup') IS NOT NULL,
'security_migration',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name)) FROM supabase_migrations.schema_migrations WHERE version='20261113235412' OR name ILIKE '%seguridad_supabase_02%')
) snapshot; COMMIT;
